<?php
// Run with the multipart fixtures generated by run-sqlite.sh: file[0] large, file[1] small.
// Dispatches the real site admin > Resources controller action as a site admin without view-all.
chdir(getenv('DISKQUOTA_TEST_ROOT'));
require 'bootstrap.php';

try {
    $app = Omeka\Mvc\Application::init(require 'application/config/application.config.php');
    $services = $app->getServiceManager();
    // Run UpdateSiteItems in this process so its item_site writes are visible right away.
    $services->setAllowOverride(true);
    $services->setAlias('Omeka\Job\DispatchStrategy', 'Omeka\Job\DispatchStrategy\Synchronous');
    $db = $services->get('Omeka\Connection');
    $api = $services->get('Omeka\ApiManager');
    $em = $services->get('Omeka\EntityManager');
    $auth = $services->get('Omeka\AuthenticationService');
    $acl = $services->get('Omeka\Acl');
    $admin = $em->getRepository(Omeka\Entity\User::class)->findOneBy(['email' => 'admin@example.com']);
    $auth->getStorage()->write($admin);
    $services->get('Omeka\Settings')->set('media_type_whitelist', ['text/plain', 'application/octet-stream']);
    $files = $services->get('Request')->getFiles()->toArray();
    $failures = 0;
    $check = function ($valid, $message) use (&$failures) {
        echo ($valid ? 'PASS: ' : 'FAIL: ') . $message . "\n";
        $failures += $valid ? 0 : 1;
    };
    $author = function (string $email) use ($api, $services) {
        $user = $api->create('users', [
            'o:name' => $email, 'o:email' => $email, 'o:role' => 'author', 'o:is_active' => true,
        ])->getContent();
        $users = $services->get('Omeka\Settings\User');
        $users->setTargetId($user->id());
        $users->set('diskquota_user_quota', 0);
        return $user;
    };
    $users = $services->get('Omeka\Settings\User');
    $users->setTargetId($admin->getId());
    $users->set('diskquota_user_quota', 0);
    $owner = $author('private-owner@example.com');
    $siteAdmin = $author('site-admin@example.com');
    $site = $api->create('sites', [
        'o:title' => 'Resources', 'o:slug' => 'resources-quota', 'o:theme' => 'default',
        'o:site_permission' => [['o:user' => ['o:id' => $siteAdmin->id()], 'o:role' => 'admin']],
    ])->getContent();
    $siteSettings = $services->get('Omeka\Settings\Site');
    $siteSettings->setTargetId($site->id());
    $siteSettings->set('diskquota_site_quota', 1);
    $upload = fn ($index) => ['o:ingester' => 'upload', 'file_index' => $index];
    // 800 KiB private to another author, 400 KiB public: together they exceed the 1 MiB site.
    $private = $api->create('items', [
        'o:owner' => ['o:id' => $owner->id()], 'o:is_public' => false, 'o:site' => [], 'o:media' => [$upload(0)],
    ], $files)->getContent();
    $public = $api->create('items', ['o:site' => [], 'o:media' => [$upload(1)]], $files)->getContent();

    $auth->getStorage()->write($em->find(Omeka\Entity\User::class, $siteAdmin->id()));
    $check(!$acl->userIsAllowed('Omeka\Entity\Resource', 'view-all'), 'the site admin cannot view private items');
    $services->get('ControllerPluginManager')->get('currentSite')
        ->setSite($api->read('sites', $site->id())->getContent());
    $form = $services->get('FormElementManager')->get(Omeka\Form\SiteResourcesForm::class);
    $csrf = array_values(array_filter($form->getElements(), fn ($e) => $e instanceof Laminas\Form\Element\Csrf))[0];
    $submit = function (array $itemIds, string $action = 'add') use ($app, $services, $csrf, $auth, $em, $siteAdmin) {
        // Each real request loads its identity; the synchronous job clears the entity manager.
        $auth->getStorage()->write($em->find(Omeka\Entity\User::class, $siteAdmin->id()));
        $request = new Laminas\Http\Request();
        $request->setUri('http://localhost/admin/site/s/resources-quota/resources');
        $request->setMethod(Laminas\Http\Request::METHOD_POST);
        $request->setPost(new Laminas\Stdlib\Parameters([
            'item_assignment_action' => $action,
            'item_pool' => http_build_query(['id' => $itemIds]),
            'save_search' => '0',
            $csrf->getName() => $csrf->getValue(),
        ]));
        $router = $services->get('Router');
        $routeMatch = $router->match($request);
        $response = new Laminas\Http\Response();
        $event = new Laminas\Mvc\MvcEvent();
        $event->setApplication($app)->setRequest($request)->setResponse($response)
            ->setRouter($router)->setRouteMatch($routeMatch);
        $controller = $services->get('ControllerManager')->get('Omeka\Controller\SiteAdmin\Index');
        $controller->setEvent($event);
        $controller->dispatch($request, $response);
        return $response;
    };
    $jobs = fn () => (int) $db->fetchOne('SELECT COUNT(*) FROM job WHERE class = ?', ['Omeka\Job\UpdateSiteItems']);
    $assigned = fn () => array_map('intval', $db->fetchFirstColumn(
        'SELECT item_id FROM item_site WHERE site_id = ? ORDER BY item_id',
        [$site->id()]
    ));

    $before = $jobs();
    $response = $submit([$private->id(), $public->id()]);
    $check(
        $response->getStatusCode() === 302 && $jobs() === $before,
        'a pool with private items over quota is rejected'
    );
    $check($assigned() === [], 'the rejected assignment queues no job and assigns nothing');
    $check(!$acl->userIsAllowed('Omeka\Entity\Resource', 'view-all'), 'view-all is revoked after the check');

    // Laminas' redirect plugin keeps the first response, so only the job and item_site prove this one.
    $submit([$public->id()]);
    $check($jobs() === $before + 1, 'a pool that fits runs the core job');
    $check($assigned() === [$public->id()], 'the accepted assignment reaches item_site');

    // Replace unassigns the site first: the result is the pool alone, whatever the site held.
    // The synchronous core job above left view-all granted in this process; visibility is covered.
    $submit([$private->id(), $public->id()], 'replace');
    $check($jobs() === $before + 1, 'a replace pool over quota queues no job');
    $check($assigned() === [$public->id()], 'the rejected replace keeps the current assignment');
    $submit([$private->id()], 'replace');
    $check($jobs() === $before + 2, 'a replace pool that fits runs the core job');
    $check($assigned() === [$private->id()], 'the accepted replace swaps the site items');
    echo 'AUDIT_RESULT=' . ($failures ? 'FAIL' : 'PASS') . "\n";
    if ($failures) {
        http_response_code(500);
    }
} catch (Throwable $e) {
    http_response_code(500);
    echo get_class($e) . ': ' . $e->getMessage() . "\nAUDIT_RESULT=FAIL\n";
    if ($e instanceof Omeka\Api\Exception\ValidationException) {
        echo json_encode($e->getErrorStore()->getErrors(), JSON_PRETTY_PRINT) . "\n";
    }
}
